// seed: tests/seed.user.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { startMonitoring, slide } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });
test.setTimeout(180_000);

test.describe('Сводка мониторинга', () => {
  test('Сводка после двух тревог: «2 התרעות במהלך הניטור» #25e8f258 @iphone @data', async ({ page }) => {
    const falseAlarm = page.getByRole('button', { name: 'זו אזעקת שווא' }).filter({ visible: true });

    // 1. startMonitoring(page, 'headUnder')
    await startMonitoring(page, 'headUnder');

    // 2. Первая тревога: слайдер «זו אזעקת שווא» → свайп → слайдер исчез
    await expect(falseAlarm).toBeVisible({ timeout: 30_000 });
    await slide(page, 'זו אזעקת שווא');
    await expect(falseAlarm).toHaveCount(0, { timeout: 15_000 });

    // 3. Вторая тревога: слайдер снова → свайп → слайдер исчез
    await expect(falseAlarm).toBeVisible({ timeout: 60_000 });
    await slide(page, 'זו אזעקת שווא');
    await expect(falseAlarm).toHaveCount(0, { timeout: 15_000 });

    // 4. Свайп «כבה את המצלמה» — дождаться /monitor/summary
    await slide(page, 'כבה את המצלמה');
    await page.waitForURL(/\/monitor\/summary/, { timeout: 15_000 });

    await expect(page.getByText('2 התרעות במהלך הניטור').filter({ visible: true })).toBeVisible();
    expect(await page.getByText('סומן כאזעקת שווא').filter({ visible: true }).count()).toBeGreaterThanOrEqual(1);
    await expect(page.getByRole('button', { name: 'לכל הניטורים' }).filter({ visible: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'חזרה לבית' }).filter({ visible: true })).toBeVisible();
  });
});
